+		process.env[MXC_SDK_DIR_ENV]?.trim(),
+		...packagedRoots.map(
+			(root) =>
+				root && join(root, "mxc", "node_modules", "@microsoft", "mxc-sdk"),
+		),
+	];
+	return dirs
+		.filter((dir): dir is string => Boolean(dir))
+		.map((dir) => join(dir, "dist", "v1", "index.js"));
